function isLeap(year) {
  if (year % 4 === 0) {
    if (year % 100 === 0) {
      if (year % 400 === 0) {
        return "Leap year.";
      } else {
        return "Not leap year.";
      }
    } else {
      return "Leap year.";
    }
  } else {
    return "Not leap year.";
  }
}

function leapYear(year) {
  if ((year % 4 === 0 && year % 100 !== 0) || year % 400 === 0) {
    return "Leap year.";
  } else {
    return "Not leap year.";
  }
}

solution_code.code:
function isLeap(year) {
  if (year % 4 === 0) {
    if (year % 100 === 0) {
      return year % 400 === 0 ? "Leap year." : "Not leap year.";
    }
    return "Leap year.";
  }
  return "Not leap year.";
}
